#!/usr/bin/env bash
# Vendors the pinned llama.cpp sources used by Lumen's in-process embedder and
# regenerates the cgo wrapper files that compile them.
#
# Usage: internal/llama/update-llama.sh
#
# The script is deterministic: it fetches exactly LLAMA_COMMIT, refuses any
# other revision, copies only the CPU, Metal, and llama sources needed for
# embedding inference, and rewrites every generated file. To upgrade llama.cpp,
# change LLAMA_TAG/LLAMA_COMMIT/GGML_VERSION, run the script, and review the
# diff together with the real-model test in internal/embedder.
set -euo pipefail

LLAMA_REPO="https://github.com/ggml-org/llama.cpp"
LLAMA_TAG="v0.6.0"
LLAMA_COMMIT="d81235049384534c167caea52b85a694f6103d14"
LLAMA_VERSION="0.6.0"
GGML_VERSION="0.26.0"

here="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
csrc="$here/csrc"
pkgs="$here/internal"
short="${LLAMA_COMMIT:0:7}"

work="$(mktemp -d)"
trap 'rm -rf "$work"' EXIT

git -c advice.detachedHead=false clone --quiet --depth 1 --branch "$LLAMA_TAG" "$LLAMA_REPO" "$work/llama.cpp"
actual="$(git -C "$work/llama.cpp" rev-parse HEAD)"
if [ "$actual" != "$LLAMA_COMMIT" ]; then
	echo "llama.cpp tag $LLAMA_TAG resolved to $actual, expected $LLAMA_COMMIT" >&2
	exit 1
fi
src="$work/llama.cpp"

rm -rf "$csrc"
mkdir -p "$csrc/include" "$csrc/src/models" "$csrc/ggml/include" "$csrc/ggml/src"

cp "$src/LICENSE" "$csrc/LICENSE"
cp "$src/include/llama.h" "$csrc/include/"
cp "$src/ggml/include/"*.h "$csrc/ggml/include/"
cp "$src/src/"*.h "$src/src/"*.cpp "$csrc/src/"
cp "$src/src/models/"*.h "$src/src/models/"*.cpp "$csrc/src/models/"
cp "$src/ggml/src/"*.h "$src/ggml/src/"*.c "$src/ggml/src/"*.cpp "$csrc/ggml/src/"

# CPU backend: portable sources plus the x86 and ARM kernels for the release
# targets. Other architectures, KleidiAI, and SpacemiT are not built.
mkdir -p "$csrc/ggml/src/ggml-cpu"
cp "$src/ggml/src/ggml-cpu/"*.h "$src/ggml/src/ggml-cpu/"*.c "$src/ggml/src/ggml-cpu/"*.cpp "$csrc/ggml/src/ggml-cpu/"
for dir in amx llamafile tiled arch/x86 arch/arm; do
	mkdir -p "$csrc/ggml/src/ggml-cpu/$dir"
	cp "$src/ggml/src/ggml-cpu/$dir/"* "$csrc/ggml/src/ggml-cpu/$dir/"
done

# Metal backend (macOS arm64). Kernel sources are embedded below.
mkdir -p "$csrc/ggml/src/ggml-metal"
cp "$src/ggml/src/ggml-metal/"*.h "$src/ggml/src/ggml-metal/"*.cpp "$src/ggml/src/ggml-metal/"*.m "$csrc/ggml/src/ggml-metal/"

cat >"$csrc/ggml/src/ggml-version.h" <<EOF
#pragma once

#define GGML_VERSION "$GGML_VERSION"
#define GGML_COMMIT  "$short"
EOF
cat >"$csrc/src/llama-version.h" <<EOF
#pragma once

#define LLAMA_VERSION "$LLAMA_VERSION"
#define LLAMA_COMMIT  "$short"
EOF

header="Code generated by internal/llama/update-llama.sh from llama.cpp $LLAMA_TAG ($LLAMA_COMMIT). DO NOT EDIT."

# wrap <package dir> <wrapper name> <path relative to csrc>...
# Each wrapper is one translation unit; several paths form a unity build.
wrap() {
	local dir="$1" name="$2"
	shift 2
	{
		echo "// $header"
		echo
		for f in "$@"; do
			echo "#include \"../../csrc/$f\""
		done
	} >"$pkgs/$dir/$name"
}

for dir in ggmlbase ggmlcpu ggmlmetal llamacore llamamodels; do
	mkdir -p "$pkgs/$dir"
	find "$pkgs/$dir" -type f ! -name '*.go' -delete
done

for f in ggml.c ggml-alloc.c ggml-quants.c; do
	wrap ggmlbase "$f" "ggml/src/$f"
done
for f in ggml.cpp ggml-backend.cpp ggml-backend-meta.cpp ggml-backend-reg.cpp ggml-backend-dl.cpp ggml-opt.cpp ggml-threading.cpp gguf.cpp; do
	wrap ggmlbase "$f" "ggml/src/$f"
done

for f in ggml-cpu.c quants.c; do
	wrap ggmlcpu "$f" "ggml/src/ggml-cpu/$f"
done
for f in ggml-cpu.cpp repack.cpp hbm.cpp traits.cpp binary-ops.cpp unary-ops.cpp vec.cpp ops.cpp; do
	wrap ggmlcpu "$f" "ggml/src/ggml-cpu/$f"
done
wrap ggmlcpu amx-amx.cpp ggml/src/ggml-cpu/amx/amx.cpp
wrap ggmlcpu amx-mmq.cpp ggml/src/ggml-cpu/amx/mmq.cpp
wrap ggmlcpu tiled.cpp ggml/src/ggml-cpu/tiled/tiled.cpp
wrap ggmlcpu tiled-kernel.cpp ggml/src/ggml-cpu/tiled/tiled-kernel.cpp
wrap ggmlcpu llamafile-sgemm.cpp ggml/src/ggml-cpu/llamafile/sgemm.cpp
wrap ggmlcpu arch-x86-quants_amd64.c ggml/src/ggml-cpu/arch/x86/quants.c
wrap ggmlcpu arch-x86-repack_amd64.cpp ggml/src/ggml-cpu/arch/x86/repack.cpp
wrap ggmlcpu arch-arm-quants_arm64.c ggml/src/ggml-cpu/arch/arm/quants.c
wrap ggmlcpu arch-arm-repack_arm64.cpp ggml/src/ggml-cpu/arch/arm/repack.cpp

for f in ggml-metal.cpp ggml-metal-device.cpp ggml-metal-common.cpp ggml-metal-fusion.cpp ggml-metal-ops.cpp ggml-metal-tuning.cpp; do
	wrap ggmlmetal "${f%.cpp}_darwin_arm64.cpp" "ggml/src/ggml-metal/$f"
done
for f in ggml-metal-device.m ggml-metal-context.m; do
	wrap ggmlmetal "${f%.m}_darwin_arm64.m" "ggml/src/ggml-metal/$f"
done

for f in "$csrc/src/"*.cpp; do
	f="$(basename "$f")"
	wrap llamacore "$f" "src/$f"
done

# Model graph builders are compiled as unity batches of eight, matching the
# upstream CMake unity build of src/models.
models=()
while IFS= read -r f; do
	models+=("src/models/$f")
done < <(cd "$csrc/src/models" && ls -1 ./*.cpp | sed 's|^\./||' | LC_ALL=C sort)
batch=0
for ((i = 0; i < ${#models[@]}; i += 8)); do
	wrap llamamodels "$(printf 'models-%02d.cpp' "$batch")" "${models[@]:i:8}"
	batch=$((batch + 1))
done

# Embed Metal kernel sources the same way upstream CMake does with
# GGML_METAL_EMBED_LIBRARY: each kind is the concatenation of the shared
# headers it includes followed by its own source, with local includes removed
# and ggml-common.h / ggml-metal-impl.h inlined. Shared pieces are stored once
# and concatenated by the assembler.
kernels="$src/ggml/src/ggml-metal/kernels"
outk="$pkgs/ggmlmetal/kernels"
mkdir -p "$outk"
process() {
	sed -e '/#include "common.h"/d' -e '/#include "dequantize.h"/d' -e '/#include "quantize.h"/d' \
		-e '/#include "fa_common.metal"/d' -e '/#include "fa_vec_common.metal"/d' -e '/#pragma once/d' <"$1" |
		sed -e "/__embed_ggml-common.h__/r $src/ggml/src/ggml-common.h" -e '/__embed_ggml-common.h__/d' |
		sed -e "/#include \"ggml-metal-impl.h\"/r $src/ggml/src/ggml-metal/ggml-metal-impl.h" -e '/#include "ggml-metal-impl.h"/d'
}
for f in common.h dequantize.h quantize.h fa_common.metal fa_vec_common.metal; do
	process "$kernels/$f" >"$outk/$f.inc"
done
kinds="$(sed -n '/^set(METALLIB_KERNEL_SOURCES/,/^)/p' "$src/ggml/src/ggml-metal/CMakeLists.txt" | grep -o 'kernels/[a-z0-9_]*\.metal' | sed -e 's|kernels/||' -e 's|\.metal$||')"
asm="$pkgs/ggmlmetal/metallib_darwin_arm64.S"
{
	echo "// $header"
	echo
	echo "	.section __DATA,__ggml_metallib"
} >"$asm"
for kind in $kinds; do
	process "$kernels/$kind.metal" >"$outk/$kind.metal.inc"
	{
		echo "	.globl _ggml_metallib_${kind}_start"
		echo "_ggml_metallib_${kind}_start:"
		echo "	.incbin \"kernels/common.h.inc\""
		for dep in dequantize.h quantize.h fa_common.metal fa_vec_common.metal; do
			if grep -q "#include \"$dep\"" "$kernels/$kind.metal"; then
				echo "	.incbin \"kernels/$dep.inc\""
			fi
		done
		echo "	.incbin \"kernels/$kind.metal.inc\""
		echo "	.globl _ggml_metallib_${kind}_end"
		echo "_ggml_metallib_${kind}_end:"
	} >>"$asm"
done

echo "Vendored llama.cpp $LLAMA_TAG ($LLAMA_COMMIT) into $csrc"
